SET NAMES utf8mb4;
CREATE TABLE moradores (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NOT NULL, nome VARCHAR(200), cpf VARCHAR(14), unidade VARCHAR(50), email VARCHAR(200), ativo TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE dependentes (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NOT NULL, morador_id INT NOT NULL, nome_completo VARCHAR(200), ativo TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE visitantes (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NOT NULL, nome_completo VARCHAR(200), tipo_documento VARCHAR(20), documento VARCHAR(30), morador_id INT NULL, cadastrado_por_tipo VARCHAR(20) NULL, cadastrado_por_morador_id INT NULL, cadastrado_por_nome VARCHAR(150) NULL, observacao TEXT NULL, ativo TINYINT(1) DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE acessos_visitantes (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NOT NULL, visitante_id INT, morador_id INT) ENGINE=InnoDB;
CREATE TABLE sessoes_portal (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NULL, morador_id INT NOT NULL, token VARCHAR(255), ativo TINYINT(1) DEFAULT 1, data_expiracao DATETIME) ENGINE=InnoDB;
CREATE TABLE registros_acesso (id INT AUTO_INCREMENT PRIMARY KEY, tenant_id INT NOT NULL, data_hora DATETIME, tipo_acesso VARCHAR(20), tipo ENUM('Morador','Visitante','Prestador') NOT NULL, placa VARCHAR(10), nome_visitante VARCHAR(200), documento_visitante VARCHAR(30), morador_id INT, dependente_id INT, unidade_destino VARCHAR(50), status VARCHAR(20), liberado TINYINT, usuario_liberou VARCHAR(100), observacao TEXT, modo_registro VARCHAR(20)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
ALTER TABLE visitantes ADD COLUMN cadastrado_por_usuario_id INT NULL, ADD COLUMN telefone_contato VARCHAR(30) NULL, ADD COLUMN telefone VARCHAR(30) NULL, ADD COLUMN celular VARCHAR(30) NULL, ADD COLUMN placa_veiculo VARCHAR(10) NULL, ADD COLUMN email VARCHAR(150) NULL, ADD COLUMN cep VARCHAR(10) NULL, ADD COLUMN endereco VARCHAR(200) NULL, ADD COLUMN numero VARCHAR(20) NULL, ADD COLUMN complemento VARCHAR(100) NULL, ADD COLUMN bairro VARCHAR(100) NULL, ADD COLUMN cidade VARCHAR(100) NULL, ADD COLUMN estado VARCHAR(2) NULL, ADD COLUMN foto VARCHAR(255) NULL, ADD COLUMN documento_arquivo VARCHAR(255) NULL;
CREATE TABLE usuarios (id INT PRIMARY KEY, nome VARCHAR(150)) ENGINE=InnoDB;
CREATE TABLE usuario_tenant (usuario_id INT, tenant_id INT) ENGINE=InnoDB;
CREATE TABLE config_visitantes_campos (tenant_id INT, campo VARCHAR(50), obrigatorio TINYINT) ENGINE=InnoDB;
